const factKeys=['native_candidate_i1','ordinary_nhsp','origin_authority','no_external_effects'];
// Facts are raw *root native collector outputs*, not caller assertion flags.
// This protocol preserves absent facts as WAITING. Root must supply its genuine
// native owner transport and retain each raw input in the same captured trace.
function nativeGates(raw,caseId,context){
 if(raw===null)return {waiting:factKeys};
 exact(raw,factKeys,'REPORT_NATIVE_GATE_FACTS_INVALID');const waiting=[];
 const required={native_candidate_i1:['complete_original_root_set','empty_set_guard','candidate_gate_order','hooks_body'],
  ordinary_nhsp:['ordinary_owners','nhsp_owners','ordinary_result','nhsp_result'],
  origin_authority:['prepared','c1','withheld','headless',...(caseId==='NEXT_ACTIVE'?['next']:[])],
  no_external_effects:['provider','settlement','email','network']};
 for(const key of factKeys){const v=raw[key];
  if(v===null){waiting.push(key);continue;}
  exact(v,['owner_signature','owner_body_sha256','request_bytes','result_bytes'],'REPORT_NATIVE_GATE_FACTS_INVALID');
  if(typeof v.owner_signature!=='string'||!/^private\.[a-z0-9_]+\([a-z0-9, .\[\]]*\)$/.test(v.owner_signature)
   ||!hex.test(v.owner_body_sha256))fail('REPORT_NATIVE_GATE_FACTS_INVALID');
  const input=rawJson(v.request_bytes,'REPORT_NATIVE_GATE_FACTS_INVALID'),result=rawJson(v.result_bytes,'REPORT_NATIVE_GATE_FACTS_INVALID');
  exact(input,['schema_version','execution','actor_user_id','source_cycle_id','report_scope_id','invoice_id','case_id','variant','native_owner_request'],'REPORT_NATIVE_GATE_FACTS_INVALID');
  if(input.schema_version!=='WEEKLY_SOURCE_REPORT_FIN_NATIVE_GATE_CAPTURE_REQUEST_V1'||!same(input.execution,context.execution)
   ||input.actor_user_id!==context.native_request.actor_user_id||input.source_cycle_id!==context.native_request.source_cycle_id
   ||input.report_scope_id!==context.native_request.report_scope_id||input.invoice_id!==context.invoice_id||input.case_id!==caseId
   ||input.variant!==context.variant||!input.native_owner_request||Array.isArray(input.native_owner_request)||typeof input.native_owner_request!=='object')
   fail('REPORT_NATIVE_GATE_SCOPE_CHANGED');
  // The controlling root mapper validates native semantic result shapes. The
  // collector cannot elevate an arbitrary {ok:true}/assertions object. These
  // are rederived gate witness bindings to actual native raw owner outputs.
  exact(result,['schema_version','execution','native_request_sha256','native_result_sha256','observations'],'REPORT_NATIVE_GATE_FACTS_INVALID');
  if(result.schema_version!=='WEEKLY_SOURCE_REPORT_FIN_NATIVE_GATE_OBSERVATION_V1'
   ||result.native_request_sha256!==sha256(v.request_bytes)
   ||!Array.isArray(result.observations)||result.observations.length!==required[key].length
   ||result.native_result_sha256!==domainHash('WEEKLY_SOURCE_REPORT_FIN_NATIVE_GATE_OBSERVATIONS_V1',result.observations)
   ||new Set(result.observations.map(o=>o.identity)).size!==result.observations.length
   ||!required[key].every(id=>result.observations.some(o=>o.identity===id)))fail('REPORT_NATIVE_GATE_FACTS_INVALID');
  for(const observation of result.observations){
   exact(observation,['identity','expected_bytes','observed_bytes'],'REPORT_NATIVE_GATE_FACTS_INVALID');
   if(typeof observation.identity!=='string'||!observation.identity||typeof observation.expected_bytes!=='string'
    ||typeof observation.observed_bytes!=='string'||observation.expected_bytes!==observation.observed_bytes)fail('REPORT_NATIVE_GATE_OBSERVATION_FAILED');
   for(const bytes of [observation.expected_bytes,observation.observed_bytes]){
    const value=rawJson(bytes,'REPORT_NATIVE_GATE_FACTS_INVALID');
    if(!value||typeof value!=='object')fail('REPORT_NATIVE_GATE_FACTS_INVALID');
   }
  }
 }
 return {waiting};
}
